import cues from '../../audio/first_game/cues.json';
import {createTimeline} from '../timeline';

/**
 * The first_game timeline, generated by tools/build_space_audio.py
 * (--episode first_game) from audio/first_game/story.json.
 */
export type Cue = keyof typeof cues.events;

export const timeline = createTimeline<Cue>(cues.events as Record<Cue, number>, cues.bpm);
export const {at, syncTo, playUntil, beat} = timeline;
export const duration = cues.duration;

/** The code Spark types, by cue (style bible K5: real code, shown exactly). */
export const code = cues.code as Record<string, string>;
/** The game's physics constants; every flight in the film obeys them. */
export const physics = cues.physics;

export interface Segment {
  t: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  until: number;
}
export interface RallyEvent {
  kind: 'serve' | 'hit' | 'wall' | 'miss' | 'tunnel' | 'goal';
  t: number;
  side?: number;
  y?: number;
  speed?: number;
}
export interface Rally {
  segments: Segment[];
  events: RallyEvent[];
}
/** Every ball flight in the film, computed by tools/pong.py. */
export const rallies = (cues as unknown as {rallies: Record<string, Rally>}).rallies;
